#include <iostream>
template <typename T>
struct is_error_condition_enum {
    static constexpr bool value = false;
};

// Specialization for errc type
enum class errc { network_error, permission_denied };
template <>
struct is_error_condition_enum<errc> {
    static constexpr bool value = true;
};

int main() {
    std::cout << std::boolalpha;
    std::cout << "is_error_condition_enum<errc>: " << is_error_condition_enum<errc>::value << std::endl;
    std::cout << "is_error_condition_enum<int>: " << is_error_condition_enum<int>::value << std::endl;
    return 0;
}
